import 'package:aws_signature_v4/aws_signature_v4.dart';

const signer = AWSSigV4Signer(
  credentialsProvider: AWSCredentialsProvider.environment(),
);

final request = AWSHttpRequest(
  method: AWSHttpMethod.post,
  uri: Uri.https('cognito-idp.us-east-1.amazonaws.com', '/'),
  headers: const {
    AWSHeaders.target: 'AWSCognitoIdentityProviderService.DescribeUserPool',
    AWSHeaders.contentType: 'application/x-amz-json-1.1',
  },
  body: const [],
);

final signed = await signer.sign(request, credentialScope: AWSCredentialScope(region: 'us-east-1', service: AWSService.cognitoIdentityProvider));
// send `signed` with any HTTP client
